describe('Alert Dialog Modal Blocking Interaction', () => {
  beforeEach(() => {
    cy.visit('about:blank');
    cy.document().then(doc => {
      doc.body.innerHTML = `
        <div id="page-content">
          <h1>Main Page Content</h1>
          <button id="trigger-alert">Open Alert</button>
          <input id="background-input" type="text" placeholder="Background input">
          <button id="background-button">Background Button</button>
        </div>
        <div id="alert-overlay" style="display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 1000;"></div>
        <div id="alert-dialog" style="display: none; position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: white; padding: 20px; border-radius: 8px; z-index: 1001; min-width: 300px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);">
          <h2>Alert</h2>
          <p id="alert-message">This is an alert dialog</p>
          <button id="alert-ok">OK</button>
        </div>
        <script>
          const triggerBtn = document.getElementById('trigger-alert');
          const alertDialog = document.getElementById('alert-dialog');
          const alertOverlay = document.getElementById('alert-overlay');
          const okBtn = document.getElementById('alert-ok');
          const bgInput = document.getElementById('background-input');
          const bgButton = document.getElementById('background-button');

          triggerBtn.addEventListener('click', () => {
            alertDialog.style.display = 'block';
            alertOverlay.style.display = 'block';
            bgInput.disabled = true;
            bgButton.disabled = true;
          });

          okBtn.addEventListener('click', () => {
            alertDialog.style.display = 'none';
            alertOverlay.style.display = 'none';
            bgInput.disabled = false;
            bgButton.disabled = false;
          });
        </script>
      `;
    });
  });

  it('should display alert dialog and block interaction with background elements', () => {
    cy.get('#trigger-alert').click();

    cy.get('#alert-dialog').should('be.visible');
    cy.get('#alert-overlay').should('be.visible');

    cy.get('#alert-dialog').should('have.css', 'z-index', '1001');
    cy.get('#alert-overlay').should('have.css', 'z-index', '1000');

    cy.get('#background-input').should('be.disabled');
    cy.get('#background-button').should('be.disabled');

    cy.get('#background-input').type('test', { force: false }).then(() => {
      cy.get('#background-input').should('have.value', '');
    });
  });

  it('should close alert dialog and restore interaction with background elements', () => {
    cy.get('#trigger-alert').click();
    cy.get('#alert-dialog').should('be.visible');

    cy.get('#alert-ok').click();

    cy.get('#alert-dialog').should('not.be.visible');
    cy.get('#alert-overlay').should('not.be.visible');

    cy.get('#background-input').should('not.be.disabled');
    cy.get('#background-button').should('not.be.disabled');

    cy.get('#background-input').type('test input');
    cy.get('#background-input').should('have.value', 'test input');
  });

  it('should prevent clicking background elements while alert is open', () => {
    const clickSpy = cy.spy();

    cy.get('#background-button').then($btn => {
      $btn.on('click', clickSpy);
    });

    cy.get('#trigger-alert').click();
    cy.get('#alert-dialog').should('be.visible');

    cy.get('#background-button').click({ force: false }).then(() => {
      expect(clickSpy).not.to.have.been.called;
    });
  });

  it('should handle multiple alert open/close cycles', () => {
    for (let i = 0; i < 3; i++) {
      cy.get('#trigger-alert').click();
      cy.get('#alert-dialog').should('be.visible');
      cy.get('#background-input').should('be.disabled');

      cy.get('#alert-ok').click();
      cy.get('#alert-dialog').should('not.be.visible');
      cy.get('#background-input').should('not.be.disabled');
    }
  });
});
